#!/usr/bin/env node
// Democracy Together presentation note (4 A4 pages), French.
//
//   node design/note-presentation/build.mjs
//
// Rebuilt from "democracy-together-presentation-fr.pdf" (no source file was
// kept). Steps: draw the dotted world map of page 2 (carte-monde.svg), collect
// the Lucide icons into visuels.js, then print note-fr.html to PDF and one PNG
// preview per page. The logo rays come from the brochure's visuels.js
// (design/plaquette, generated by its own build.mjs).
//
// Dependencies come from the repo's node_modules (d3-geo, topojson-client,
// world-atlas, lucide-react, @playwright/test). If the pinned Playwright
// browser is missing, set PLAYWRIGHT_CHROMIUM_PATH to an installed
// chrome-headless-shell.
import { createRequire } from 'node:module';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { geoContains, geoBounds } from 'd3-geo';
import { feature } from 'topojson-client';
import { chromium } from '@playwright/test';

const HERE = dirname(fileURLToPath(import.meta.url));
const require = createRequire(import.meta.url);
const f2 = (n) => Math.round(n * 100) / 100;

// ----------------------------------------------------------------- map ----

const AFRICA = new Set(
  '012 024 204 072 854 108 120 140 148 178 180 384 262 818 226 232 748 231 266 270 288 324 624 404 426 430 434 450 454 466 478 504 508 516 562 566 646 686 694 706 710 728 729 834 768 788 800 732 894 716'.split(' '),
);
const EUROPE = new Set(
  '008 040 112 056 070 100 191 196 203 208 233 246 250 276 300 348 352 372 380 428 440 442 498 499 528 807 578 616 620 642 688 703 705 724 752 756 804 826'.split(' '),
);
const NAMED = new Set(['Somaliland', 'Kosovo', 'N. Cyprus']);

const topo = JSON.parse(readFileSync(require.resolve('world-atlas/countries-110m.json'), 'utf8'));
const COUNTRIES = feature(topo, topo.objects.countries).features.map((f) => {
  const [[x0, y0], [x1, y1]] = geoBounds(f);
  return { f, x0, y0, x1, y1 };
});
function countryAt([lon, lat]) {
  return COUNTRIES.find(
    (c) =>
      lat >= c.y0 && lat <= c.y1 &&
      (c.x0 <= c.x1 ? lon >= c.x0 && lon <= c.x1 : lon >= c.x0 || lon <= c.x1) &&
      geoContains(c.f, [lon, lat]),
  )?.f;
}

// Active (Africa, Europe), deploying (the Americas), soon (Asia), other.
function region(f, lon, lat) {
  if (f.id === '250' && lon < -30) return 'americas'; // French Guiana
  if (AFRICA.has(f.id) || EUROPE.has(f.id) || NAMED.has(f.properties.name)) return 'active';
  if (lon < -25) return 'americas';
  if (lon > 25 && lat > -11) return 'asia';
  return 'other';
}

// Flat (equirectangular) dotted map on a hexagonal grid, on deep indigo.
function worldMap() {
  const W = 360;
  const LAT_TOP = 80;
  const LAT_BOTTOM = -56;
  const H = LAT_TOP - LAT_BOTTOM;
  const step = 2.6;
  const dot = 0.95;
  const style = {
    active: 'fill="#f4f2ec"',
    americas: 'fill="#f4f2ec" fill-opacity=".55"',
    asia: 'fill="#c0814a" fill-opacity=".9"',
    other: 'fill="#f4f2ec" fill-opacity=".28"',
  };
  const dots = { active: [], americas: [], asia: [], other: [] };
  let row = 0;
  for (let lat = LAT_TOP - step / 2; lat > LAT_BOTTOM; lat -= step * 0.866, row++) {
    const offset = row % 2 ? step / 2 : 0;
    for (let lon = -180 + offset + step / 2; lon < 180; lon += step) {
      const f = countryAt([lon, lat]);
      if (!f) continue;
      const k = region(f, lon, lat);
      dots[k].push(`<circle cx="${f2(lon + 180)}" cy="${f2(LAT_TOP - lat)}" r="${dot}"/>`);
    }
  }
  const groups = Object.entries(dots)
    .map(([k, list]) => `<g ${style[k]}>${list.join('')}</g>`)
    .join('\n');
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}">\n${groups}\n</svg>\n`;
  writeFileSync(join(HERE, 'carte-monde.svg'), svg);
  return `carte-monde.svg: ${Object.entries(dots).map(([k, l]) => `${k} ${l.length}`).join(', ')}`;
}

// --------------------------------------------------------------- icons ----

const ICONS = ['pen-line', 'user-round-search', 'badge-check', 'lock-open', 'user-check', 'network', 'mail', 'globe'];

async function icons() {
  const dir = join(dirname(require.resolve('lucide-react/package.json')), 'dist', 'esm', 'icons');
  const out = [];
  for (const name of ICONS) {
    const { __iconData } = await import(pathToFileURL(join(dir, `${name}.mjs`)).href);
    const body = __iconData.node
      .map(([tag, attrs]) => {
        const a = Object.entries(attrs)
          .filter(([k]) => k !== 'key')
          .map(([k, v]) => `${k}="${v}"`)
          .join(' ');
        return `<${tag} ${a}/>`;
      })
      .join('');
    out.push(
      `<symbol id="ico-${name}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${body}</symbol>`,
    );
  }
  const sprite = `<svg xmlns="http://www.w3.org/2000/svg" aria-hidden="true" style="position:absolute;width:0;height:0"><defs>${out.join('')}</defs></svg>`;
  writeFileSync(
    join(HERE, 'visuels.js'),
    `// Generated by build.mjs: Lucide icons as an inline SVG sprite.\ndocument.body.insertAdjacentHTML('afterbegin', ${JSON.stringify(sprite)});\n`,
  );
  return `visuels.js: ${ICONS.length} icons`;
}

// --------------------------------------------------------------- print ----

async function main() {
  console.log(worldMap());
  console.log(await icons());

  const browser = await chromium.launch(
    process.env.PLAYWRIGHT_CHROMIUM_PATH ? { executablePath: process.env.PLAYWRIGHT_CHROMIUM_PATH } : {},
  );
  const page = await browser.newPage();
  await page.goto(pathToFileURL(join(HERE, 'note-fr.html')).href, { waitUntil: 'networkidle' });
  await page.evaluate(() => document.fonts.ready);
  const missing = await page.evaluate(() =>
    ['Newsreader', 'IBM Plex Sans', 'IBM Plex Mono'].filter((f) => !document.fonts.check(`12px "${f}"`)),
  );
  if (missing.length) throw new Error(`Fonts not loaded: ${missing.join(', ')}`);

  // Each .page is a fixed A4 box: report the room left under its last block.
  const room = await page.evaluate(() =>
    [...document.querySelectorAll('.page')].map((p, i) => {
      const box = p.getBoundingClientRect();
      let bottom = box.top;
      p.querySelectorAll('.flow > *').forEach((el) => {
        bottom = Math.max(bottom, el.getBoundingClientRect().bottom);
      });
      return { page: i + 1, mm: Math.round(((box.bottom - bottom) / 3.7795) * 10) / 10 };
    }),
  );
  for (const r of room) console.log(`page ${r.page}: ${r.mm} mm left${r.mm < 8 ? '  OVERFLOW' : ''}`);

  await page.pdf({ path: join(HERE, 'democracy-together-presentation-fr.pdf'), preferCSSPageSize: true, printBackground: true });
  console.log('democracy-together-presentation-fr.pdf');

  const dir = join(HERE, 'apercu');
  mkdirSync(dir, { recursive: true });
  await page.emulateMedia({ media: 'print' });
  const pages = await page.$$('.page');
  for (let i = 0; i < pages.length; i++) {
    await pages[i].screenshot({ path: join(dir, `page-${i + 1}.png`) });
  }
  console.log(`previews in apercu/ (${pages.length} pages)`);
  await browser.close();
}

await main();
